85	class Node {
86	 public:
87	  std::string DebugString() const;
88	  int id() const { return id_; }
89	  int cost_id() const { return cost_id_; }
90	  const std::string& name() const;
91	  void set_name(std::string name);
92	  const std::string& type_string() const;
93	
94	  // def() provides the NodeDef the user supplied, but the specifics
95	  // of this Node may have changed due to placement, optimization, etc.
96	  // In particular:
97	  // * def().name() will match name();
98	  // * def().op() will match type_string() and op_def().name();
99	  // * def().input() is not reliable, use "in_edges()" below instead;
100	  // * def().device() is the "user's requested device" and may not match
101	  //   the actual assigned device, see assigned_device_name() below;
102	  // * def().attr() is authoritative.
103	  // TODO(irving): Replace with NodeInfo.
104	  const NodeDef& def() const;
105	  const OpDef& op_def() const;
106	
107	  NodeDef* mutable_def();
108	
109	  // input and output types
110	  int32_t num_inputs() const;
111	  DataType input_type(int32_t i) const;
112	  const DataTypeVector& input_types() const;
113	
114	  int32_t num_outputs() const;
115	  DataType output_type(int32_t o) const;
116	  const DataTypeVector& output_types() const;
117	
118	  // The device requested by the user.  For the actual assigned device,
119	  // use assigned_device_name() below.
120	  const std::string& requested_device() const;
121	
122	  // This changes the user requested device but not necessarily the device that
123	  // on which the operation will run.
124	  void set_requested_device(const std::string& device);
125	
126	  // This gives the device the runtime has assigned this node to.  If
127	  // you want the device the user requested, use def().device() instead.
128	  // TODO(josh11b): Validate that the assigned_device, if not empty:
129	  // fully specifies a device, and satisfies def().device().
130	  // TODO(josh11b): Move assigned_device_name outside of Node into a
131	  // NodeId->DeviceName map.
132	  const std::string& assigned_device_name() const;
133	  void set_assigned_device_name(const std::string& device_name);
134	  bool has_assigned_device_name() const {
135	    return assigned_device_name_index_ > 0;
136	  }
137	  int assigned_device_name_index() const { return assigned_device_name_index_; }
138	  void set_assigned_device_name_index(int index);
139	
140	  // Sets 'original_node_names' field of this node's DebugInfo proto to
141	  // 'names'.
142	  void set_original_node_names(const std::vector<std::string>& names);
143	  void set_original_func_names(const std::vector<std::string>& names);
144	
145	  // Read only access to attributes
146	  AttrSlice attrs() const;
147	
148	  // Inputs requested by the NodeDef.  For the actual inputs, use in_edges.
149	  const protobuf::RepeatedPtrField<std::string>& requested_inputs() const;
150	
151	  // Get the neighboring nodes via edges either in or out of this node.  This
152	  // includes control edges.
153	  gtl::iterator_range<NeighborIter> in_nodes() const;
154	  gtl::iterator_range<NeighborIter> out_nodes() const;
155	  const EdgeSet& in_edges() const { return in_edges_; }
156	  const EdgeSet& out_edges() const { return out_edges_; }
157	
158	  // Node type helpers.
159	  bool IsSource() const { return id() == 0; }
160	  bool IsSink() const { return id() == 1; }
161	  // Anything other than the special Source & Sink nodes.
162	  bool IsOp() const { return id() > 1; }
163	
164	  // Node class helpers
165	  bool IsSwitch() const { return class_ == NC_SWITCH; }
166	  bool IsMerge() const { return class_ == NC_MERGE; }
167	  bool IsEnter() const { return class_ == NC_ENTER; }
168	  bool IsExit() const { return class_ == NC_EXIT; }
169	  bool IsNextIteration() const { return class_ == NC_NEXT_ITERATION; }
170	  bool IsLoopCond() const { return class_ == NC_LOOP_COND; }
171	  bool IsControlTrigger() const { return class_ == NC_CONTROL_TRIGGER; }
172	  bool IsSend() const { return class_ == NC_SEND || class_ == NC_HOST_SEND; }
173	  bool IsRecv() const { return class_ == NC_RECV || class_ == NC_HOST_RECV; }
174	  bool IsConstant() const { return class_ == NC_CONSTANT; }
175	  bool IsVariable() const { return class_ == NC_VARIABLE; }
176	  bool IsIdentity() const { return class_ == NC_IDENTITY; }
177	  bool IsGetSessionHandle() const { return class_ == NC_GET_SESSION_HANDLE; }
178	  bool IsGetSessionTensor() const { return class_ == NC_GET_SESSION_TENSOR; }
179	  bool IsDeleteSessionTensor() const {
180	    return class_ == NC_DELETE_SESSION_TENSOR;
181	  }
182	  bool IsControlFlow() const {
183	    return (class_ != NC_OTHER) &&  // Fast path
184	           (IsSwitch() || IsMerge() || IsEnter() || IsExit() ||
185	            IsNextIteration());
186	  }
187	  bool IsHostSend() const { return class_ == NC_HOST_SEND; }
188	  bool IsHostRecv() const { return class_ == NC_HOST_RECV; }
189	  bool IsScopedAllocator() const { return class_ == NC_SCOPED_ALLOCATOR; }
190	  bool IsCollective() const { return class_ == NC_COLLECTIVE; }
191	
192	  bool IsMetadata() const { return class_ == NC_METADATA; }
193	  bool IsFakeParam() const { return class_ == NC_FAKE_PARAM; }
194	  bool IsPartitionedCall() const { return class_ == NC_PARTITIONED_CALL; }
195	
196	  // Returns true if this node is any kind of function call node.
197	  //
198	  // NOTE: "function call nodes" include partitioned call ops, symbolic gradient
199	  // ops, and ops whose type_string is the name of a function ("function ops").
200	  bool IsFunctionCall() const {
201	    return class_ == NC_PARTITIONED_CALL || class_ == NC_FUNCTION_OP ||
202	           class_ == NC_SYMBOLIC_GRADIENT;
203	  }
204	
205	  bool IsIfNode() const { return class_ == NC_IF; }
206	  bool IsWhileNode() const { return class_ == NC_WHILE; }
207	  bool IsCaseNode() const { return class_ == NC_CASE; }
208	  // Is this node a function input
209	  bool IsArg() const { return class_ == NC_ARG; }
210	  // Is this node a function output
211	  bool IsRetval() const { return class_ == NC_RETVAL; }
212	
213	  bool IsDistributedCommunication() const {
214	    return op_def().is_distributed_communication();
215	  }
