229	
230	  // Returns into '*e' the edge connecting to the 'idx' input of this Node.
231	  absl::Status input_edge(int idx, const Edge** e) const;
232	
233	  // Returns into '*edges' the input data edges of this Node, indexed by input
234	  // number. Does not return control edges.
235	  absl::Status input_edges(std::vector<const Edge*>* edges) const;
236	
237	  // Returns into '*n' the node that has an output connected to the
238	  // 'idx' input of this Node.
239	  absl::Status input_node(int idx, const Node** n) const;
240	  absl::Status input_node(int idx, Node** n) const;
241	
242	  // Returns into '*t' the idx-th input tensor of this node, represented as the
243	  // output tensor of input_node(idx).
244	  absl::Status input_tensor(int idx, OutputTensor* t) const;
245	
246	  WhileContext* while_ctx() const { return while_ctx_; }
247	  void set_while_ctx(WhileContext* while_ctx) {
248	    DCHECK(IsExit());
249	    DCHECK(while_ctx_ == nullptr);
250	    while_ctx_ = while_ctx;
251	  }
252	
253	  std::shared_ptr<NodeProperties> properties() const { return props_; }
254	
255	  // Sets the stack trace for the node. Assumes that getting and setting the
256	  // stack trace for a given node will not race.
257	  void SetStackTrace(const std::shared_ptr<AbstractStackTrace>& stack_trace) {
258	    stack_trace_ = stack_trace;
259	  }
260	
261	  // Get the stack trace for when the node was instantiated.
262	  const std::shared_ptr<AbstractStackTrace>& GetStackTrace() const {
263	    return stack_trace_;
264	  }
265	
266	  // Called after an attr has changed. Decides whether we need to update some
267	  // property of the node (stored in props_).
268	  void UpdateProperties();
269	
270	  // Erases type information from the node.
271	  void ClearTypeInfo();
272	
273	  // Update type information for a node with a list of inputs and/or outputs
274	  // described by its TYPE_ATTR_NAME attr when removing some of these. The keys
275	  // of INDEX_MAPPING are the indexes of the inputs/outputs that are not
276	  // removed. dtype information in the TYPE_ATTR_NAME attr is always updated.
277	  // Use UPDATE_FULL_TYPE=true when this changes the node's outputs to also
278	  // update the node's full type information (if present).
279	  absl::Status ShrinkTypeInfo(
280	      const absl::flat_hash_map<int, int>& index_mapping,
281	      const std::string& type_attr_name, bool update_full_type);
282	
283	  // Called after an incident non-control edge has changed. Does nothing if not
284	  // all input edges are defined.
285	  void RunForwardTypeInference();
