287	 private:
288	  // TODO(mdan): Drop this.
289	  friend class Graph;
290	  Node();
291	
292	  // Stack trace for the user code for node instantiation. Can be shared across
293	  // multiple nodes (e.g. when inlining).
294	  std::shared_ptr<AbstractStackTrace> stack_trace_;
295	
296	  // Releases memory from props_, in addition to restoring *this to its
297	  // uninitialized state.
298	  void Clear();
299	
300	  // Make a copy of the Node's props_ if props_ is shared with
301	  // other nodes. This must be called before mutating properties,
302	  // e.g. in AddAttr.
303	  void MaybeCopyOnWrite();
304	
305	  AttrValue* AddAttrHelper(const std::string& name);
306	
