308	  // class_ is initialized in the Node::Initialize routine based on the
309	  // node's type_string().
310	  enum NodeClass {
311	    NC_UNINITIALIZED,
312	    NC_SWITCH,
313	    NC_MERGE,
314	    NC_ENTER,
315	    NC_EXIT,
316	    NC_NEXT_ITERATION,
317	    NC_LOOP_COND,
318	    NC_CONTROL_TRIGGER,
319	    NC_SEND,
320	    NC_HOST_SEND,
321	    NC_RECV,
322	    NC_HOST_RECV,
323	    NC_CONSTANT,
324	    NC_VARIABLE,
325	    NC_IDENTITY,
326	    NC_GET_SESSION_HANDLE,
327	    NC_GET_SESSION_TENSOR,
328	    NC_DELETE_SESSION_TENSOR,
329	    NC_METADATA,
330	    NC_SCOPED_ALLOCATOR,
331	    NC_COLLECTIVE,
332	    NC_FAKE_PARAM,
333	    NC_PARTITIONED_CALL,
334	    NC_FUNCTION_OP,
335	    NC_SYMBOLIC_GRADIENT,
336	    NC_IF,
