395	// Represents an input of a node, i.e., the `index`-th input to `node`.
396	struct InputTensor {
397	  Node* node;
398	  int index;
399	
400	  InputTensor(Node* n, int i) : node(n), index(i) {}
401	  InputTensor() : node(nullptr), index(0) {}
402	
403	  // Returns true if this InputTensor is identical to 'other'. Nodes are
404	  // compared using pointer equality.
405	  bool operator==(const InputTensor& other) const;
406	
407	  // A hash function for InputTensors. Nodes are hashed based on their pointer
408	  // value.
409	  struct Hash {
410	    uint64_t operator()(InputTensor const& s) const;
411	  };
412	};
413	
414	// Represents an output of a node, i.e., the `index`-th output of `node`. Note
415	// that a single `OutputTensor` can correspond to multiple `Edge`s if the output
416	// is consumed by multiple destination nodes.
417	struct OutputTensor {
418	  Node* node;
419	  int index;
420	
421	  OutputTensor(Node* n, int i) : node(n), index(i) {}
422	  OutputTensor() : node(nullptr), index(0) {}
423	
424	  // Returns true if this OutputTensor is identical to 'other'. Nodes are
425	  // compared using pointer equality.
426	  bool operator==(const OutputTensor& other) const;
427	
428	  // A hash function for OutputTensors. Nodes are hashed based on their pointer
429	  // value.
430	  struct Hash {
431	    uint64_t operator()(OutputTensor const& s) const;
432	  };
433	};
