470	// Allows for iteration of the edges of a Graph, by iterating the underlying
471	// Graph.edges_ vector while skipping over null entries.
472	class GraphEdgesIterable {
473	 private:
474	  const std::vector<Edge*>& edges_;
475	
476	 public:
477	  explicit GraphEdgesIterable(const std::vector<Edge*>& edges)
478	      : edges_(edges) {}
479	
480	  typedef Edge* value_type;
481	
482	  class const_iterator {
483	   private:
484	    // The underlying iterator.
485	    std::vector<value_type>::const_iterator iter_;
486	
487	    // The end of the underlying iterator.
488	    std::vector<value_type>::const_iterator end_;
489	
490	    // Advances iter_ until it reaches a non-null item, or reaches the end.
491	    void apply_filter() {
492	      while (iter_ != end_ && *iter_ == nullptr) {
493	        ++iter_;
494	      }
495	    }
496	
497	   public:
498	    const_iterator(std::vector<value_type>::const_iterator iter,
499	                   std::vector<value_type>::const_iterator end)
500	        : iter_(iter), end_(end) {
501	      apply_filter();
502	    }
503	
504	    bool operator==(const const_iterator& other) const {
505	      return iter_ == other.iter_;
506	    }
507	
508	    bool operator!=(const const_iterator& other) const {
509	      return iter_ != other.iter_;
510	    }
511	
512	    // This is the prefix increment operator (++x), which is the operator
513	    // used by C++ range iteration (for (x : y) ...).  We intentionally do not
514	    // provide a postfix increment operator.
515	    const_iterator& operator++() {
516	      ++iter_;
517	      apply_filter();
518	      return *this;
519	    }
520	
521	    value_type operator*() { return *iter_; }
522	  };
523	
524	  const_iterator begin() {
525	    return const_iterator(edges_.begin(), edges_.end());
526	  }
527	  const_iterator end() { return const_iterator(edges_.end(), edges_.end()); }
528	};
