530	// Thread compatible but not thread safe.
531	class Graph {
532	 public:
533	  // Constructs a graph with a single SOURCE (always id kSourceId) and a
534	  // single SINK (always id kSinkId) node, and an edge from SOURCE->SINK.
535	  //
536	  // The graph can hold ops found in the registry. `ops`s lifetime must be at
537	  // least that of the constructed graph's.
538	  explicit Graph(const OpRegistryInterface* ops);
539	
540	  // Constructs a graph with a single SOURCE (always id kSourceId) and a
541	  // single SINK (always id kSinkId) node, and an edge from SOURCE->SINK.
542	  //
543	  // The graph can hold ops found in `flib_def`. Unlike the constructor taking
544	  // an OpRegistryInterface, this constructor copies the function definitions in
545	  // `flib_def` so its lifetime may be shorter than that of the graph's. The
546	  // OpRegistryInterface backing `flib_def` must still have the lifetime of the
547	  // graph though.
548	  explicit Graph(const FunctionLibraryDefinition& flib_def);
549	
550	  ~Graph();
551	
552	  // Clone the current graph into a new one.
553	  std::unique_ptr<Graph> Clone();
554	
555	  static constexpr int kControlSlot = -1;
556	
557	  // The GraphDef version range of this graph (see graph.proto).
558	  const VersionDef& versions() const;
559	  void set_versions(const VersionDef& versions);
560	
561	  // Adds a new node to this graph, and returns it. Infers the Op and
562	  // input/output types for the node. *this owns the returned instance.
563	  // Returns nullptr and sets *status on error.
564	  Node* AddNode(NodeDef node_def, absl::Status* status);
565	
566	  // Same as above, but using StatusOr. This method is always preferred.
567	  absl::StatusOr<Node*> AddNode(NodeDef node_def);
568	
569	  // Copies *node, which may belong to another graph, to a new node,
570	  // which is returned.  Does not copy any edges.  *this owns the
571	  // returned instance.
572	  Node* CopyNode(const Node* node);
573	
574	  // Removes a node from this graph, including all edges from or to it.
575	  // *node should not be accessed after calling this function.
576	  // REQUIRES: node->IsOp()
577	  void RemoveNode(Node* node);
578	
579	  void Copy(const Graph& src);
580	
581	  // Removes all nodes from this graph, including all edges from or to them.
582	  // No Node* references to the Graph are valid post.
583	  void Clear();
584	
585	  // Adds an edge that connects the xth output of `source` to the yth input of
586	  // `dest` and returns it. Does not update dest's NodeDef.
587	  const Edge* AddEdge(Node* source, int x, Node* dest, int y);
588	
589	  // Adds a control edge (no data flows along this edge) that connects `source`
590	  // to `dest`. If `dest`s NodeDef is missing the corresponding control input,
591	  // adds the control input.
592	  //
593	  // If such a control edge already exists and `allow_duplicates` is false, no
594	  // edge is added and the function returns nullptr. Otherwise the edge is
595	  // unconditionally created and returned. The NodeDef is not updated if
