977	// Iterator for stepping through the nodes of a graph.
978	class NodeIter {
979	 public:
980	  using iterator_category = std::forward_iterator_tag;
981	  using value_type = Node;
982	  using difference_type = std::ptrdiff_t;
983	  using pointer = Node*;
984	  using reference = Node*;
985	
986	  NodeIter(const Graph* graph, int id);
987	  bool operator==(const NodeIter& rhs) const;
988	  bool operator!=(const NodeIter& rhs) const;
989	  void operator++();
990	  reference operator*() const;
991	  pointer operator->() const;
992	
993	 private:
994	  // Invariant: id_ == graph_->num_node_ids() || graph_->FindId(id_) != nullptr
995	  const Graph* graph_;
996	  int id_;
997	};
