999	// Iterator for stepping through the neighbors of a node.
1000	class NeighborIter {
1001	 public:
1002	  using iterator_category = std::forward_iterator_tag;
1003	  using value_type = Node;
1004	  using difference_type = std::ptrdiff_t;
1005	  using pointer = Node*;
1006	  using reference = Node*;
1007	
1008	  NeighborIter(EdgeSet::const_iterator iter, bool incoming);
1009	  bool operator==(const NeighborIter& rhs) const;
1010	  bool operator!=(const NeighborIter& rhs) const;
1011	  void operator++();
1012	  reference operator*() const;
1013	  pointer operator->() const;
1014	
1015	 private:
1016	  EdgeSet::const_iterator iter_;
1017	  bool incoming_;
1018	};
