1020	// IMPLEMENTATION DETAILS, PLEASE IGNORE
1021	
1022	inline NodeIter::NodeIter(const Graph* graph, int id)
1023	    : graph_(graph), id_(id) {}
1024	
1025	inline bool NodeIter::operator==(const NodeIter& rhs) const {
1026	  DCHECK(graph_ == rhs.graph_);
1027	  return id_ == rhs.id_;
1028	}
1029	
1030	inline bool NodeIter::operator!=(const NodeIter& rhs) const {
1031	  return !(*this == rhs);
1032	}
1033	
1034	inline void NodeIter::operator++() {
1035	  while (true) {
1036	    DCHECK_LE(id_, graph_->num_node_ids());
1037	    ++id_;
1038	    if (id_ >= graph_->num_node_ids() || graph_->FindNodeId(id_) != nullptr) {
1039	      return;
1040	    }
1041	  }
1042	}
1043	
1044	inline Node* NodeIter::operator*() const { return graph_->FindNodeId(id_); }
1045	
1046	inline Node* NodeIter::operator->() const { return graph_->FindNodeId(id_); }
1047	
1048	inline NeighborIter::NeighborIter(EdgeSet::const_iterator iter, bool incoming)
1049	    : iter_(iter), incoming_(incoming) {}
1050	
1051	inline bool NeighborIter::operator==(const NeighborIter& rhs) const {
1052	  return iter_ == rhs.iter_ && incoming_ == rhs.incoming_;
1053	}
1054	
1055	inline bool NeighborIter::operator!=(const NeighborIter& rhs) const {
1056	  return !(*this == rhs);
1057	}
1058	
1059	inline void NeighborIter::operator++() { ++iter_; }
1060	
1061	inline Node* NeighborIter::operator*() const {
1062	  const Edge* e = *iter_;
1063	  return incoming_ ? e->src() : e->dst();
1064	}
1065	
1066	inline Node* NeighborIter::operator->() const {
1067	  const Edge* e = *iter_;
1068	  return incoming_ ? e->src() : e->dst();
1069	}
1070	
1071	inline bool Edge::IsControlEdge() const {
1072	  // Note that if either src_output_ or dst_input_ is kControlSlot,
1073	  // so is the other one (AddEdge checks this).
1074	  return src_output_ == Graph::kControlSlot;
1075	}
1076	
1077	inline gtl::iterator_range<NodeIter> Graph::nodes() const {
1078	  // Note that NodeId 0 is always valid since we don't let the source
1079	  // node be removed from the graph.
1080	  return gtl::make_range(NodeIter(this, 0), NodeIter(this, num_node_ids()));
1081	}
1082	
1083	inline gtl::iterator_range<NodeIter> Graph::op_nodes() const {
1084	  // Note that NodeId 0 is always valid since we don't let the source
1085	  // node be removed from the graph.
1086	  //
1087	  // The current implementation of Graph maintains the invariant that the
1088	  // first two nodes are the source and sink nodes, and all other nodes are op
1089	  // nodes. This method (op_nodes()) relies on this invariant.
1090	  NodeIter begin(this, 0);
1091	  NodeIter end(this, num_node_ids());
1092	  if (begin != end) {
1093	    ++begin;
1094	  }
1095	  if (begin != end) {
1096	    ++begin;
1097	  }
1098	  return gtl::make_range(begin, end);
1099	}
