51	Node::NodeClass Node::GetNodeClassForOp(const std::string& ts) {
52	  static const absl::flat_hash_map<std::string, Node::NodeClass>*
53	      kNodeClassTable =
54	#define REF_CLASS(key, value) \
55	  {key, value}, { "Ref" key, value }
56	          new absl::flat_hash_map<std::string, Node::NodeClass>({
57	              // Keep in same order as NodeClass values
58	              REF_CLASS("Switch", NC_SWITCH),
59	              REF_CLASS("_SwitchN", NC_SWITCH),
60	              REF_CLASS("Merge", NC_MERGE),
61	              REF_CLASS("Enter", NC_ENTER),
62	              REF_CLASS("Exit", NC_EXIT),
63	              REF_CLASS("NextIteration", NC_NEXT_ITERATION),
64	              {"LoopCond", NC_LOOP_COND},
65	              {"ControlTrigger", NC_CONTROL_TRIGGER},
66	              {"_Send", NC_SEND},
67	              {"_HostSend", NC_HOST_SEND},
68	              {"_Recv", NC_RECV},
69	              {"_HostRecv", NC_HOST_RECV},
70	              {"Const", NC_CONSTANT},
71	              {"HostConst", NC_CONSTANT},
72	              {"Variable", NC_VARIABLE},
73	              {"VariableV2", NC_VARIABLE},
74	              REF_CLASS("Identity", NC_IDENTITY),
75	              {"GetSessionHandle", NC_GET_SESSION_HANDLE},
76	              {"GetSessionHandleV2", NC_GET_SESSION_HANDLE},
77	              {"GetSessionTensor", NC_GET_SESSION_TENSOR},
78	              {"DeleteSessionTensor", NC_DELETE_SESSION_TENSOR},
79	              {"Size", NC_METADATA},
80	              {"Shape", NC_METADATA},
81	              {"Rank", NC_METADATA},
82	              {"_ScopedAllocator", NC_SCOPED_ALLOCATOR},
83	              {"CollectiveReduce", NC_COLLECTIVE},
84	              {"CollectiveBcastSend", NC_COLLECTIVE},
85	              {"CollectiveBcastRecv", NC_COLLECTIVE},
86	              {"CollectiveGather", NC_COLLECTIVE},
87	              {"FakeParam", NC_FAKE_PARAM},
88	              {"PartitionedCall", NC_PARTITIONED_CALL},
89	              {"StatefulPartitionedCall", NC_PARTITIONED_CALL},
90	              {"SymbolicGradient", NC_SYMBOLIC_GRADIENT},
91	              {"If", NC_IF},
92	              {"StatelessIf", NC_IF},
93	              {"While", NC_WHILE},
94	              {"StatelessWhile", NC_WHILE},
95	              {"Case", NC_CASE},
96	              {"StatelessCase", NC_CASE},
97	              // Not using the constants defined in FunctionLibraryDefinition
