191	absl::Status Node::ShrinkTypeInfo(
192	    const absl::flat_hash_map<int, int>& index_mapping,
193	    const std::string& type_attr_name, bool update_full_type) {
194	  std::vector<DataType> dtypes;
195	  TF_RETURN_IF_ERROR(GetNodeAttr(def(), type_attr_name, &dtypes));
196	
197	  std::vector<DataType> new_dtypes;
198	  new_dtypes.reserve(index_mapping.size());
199	  for (int i = 0; i < dtypes.size(); ++i) {
200	    if (index_mapping.contains(i)) {
201	      new_dtypes.emplace_back(dtypes[i]);
202	    }
203	  }
204	
205	  ClearAttr(type_attr_name);
206	  AddAttr(type_attr_name, new_dtypes);
207	
208	  if (!update_full_type || !def().has_experimental_type()) {
209	    return absl::OkStatus();
210	  }
211	  FullTypeDef ft = def().experimental_type();
212	  if (ft.type_id() != TFT_PRODUCT) {
213	    return absl::InternalError(absl::StrCat(
214	        "In ShrinkTypeInfo, full type information does not start with "
215	        "TFT_PRODUCT\n",
216	        ft.DebugString()));
217	  }
218	  if (ft.args_size() != dtypes.size()) {
219	    return absl::InternalError(
220	        absl::StrCat("In ShrinkTypeInfo, ft.args_size() ", ft.args_size(),
221	                     " != dtypes.size() ", dtypes.size()));
222	  }
223	  FullTypeDef new_ft;
224	  new_ft.set_type_id(TFT_PRODUCT);
225	  for (int i = 0; i < ft.args_size(); ++i) {
226	    if (index_mapping.contains(i)) {
227	      (*new_ft.add_args()) = ft.args(i);
228	    }
229	  }
230	  MaybeCopyOnWrite();
231	  *(mutable_def()->mutable_experimental_type()) = new_ft;
232	  return absl::OkStatus();
233	}
