319	absl::Status Node::input_edge(int idx, const Edge** e) const {
320	  if (idx < 0 || idx >= num_inputs()) {
321	    return absl::InvalidArgumentError(
322	        absl::StrCat("Invalid input_edge index: ", idx, ", Node ", name(),
323	                     " only has ", num_inputs(), " inputs."));
324	  }
325	
326	  // This does a linear search over the edges.  In the common case,
327	  // the number of elements is small enough that this search isn't
328	  // expensive.  Should it become a bottleneck, one can make an
329	  // optimization where, if the number of edges is small, we use
330	  // linear iteration, and if the number of edges is large, we perform
331	  // an indexing step during construction that keeps an array of Edges
332	  // indexed by pointer.  This would keep the size of each Node small
333	  // in the common case but make this function faster when the number
334	  // of edges is large.
335	  for (const Edge* edge : in_edges()) {
336	    if (edge->dst_input() == idx) {
337	      *e = edge;
338	      return absl::OkStatus();
339	    }
340	  }
341	
342	  return absl::NotFoundError(
343	      absl::StrCat("Could not find input edge ", idx, " for ", name()));
344	}
