346	// Returns a vector of the non-control input edges to a node, indexed by ID.
347	absl::Status Node::input_edges(std::vector<const Edge*>* input_edges) const {
348	  input_edges->clear();
349	  input_edges->resize(num_inputs(), nullptr);
350	
351	  for (const Edge* edge : in_edges()) {
352	    if (edge->IsControlEdge()) continue;
353	    if (edge->dst_input() < 0 || edge->dst_input() >= num_inputs()) {
354	      return absl::InternalError(
355	          absl::StrCat("Invalid edge input number ", edge->dst_input()));
356	    }
357	    if ((*input_edges)[edge->dst_input()] != nullptr) {
358	      return absl::InternalError(
359	          absl::StrCat("Duplicate edge input number: ", edge->dst_input()));
360	    }
361	    (*input_edges)[edge->dst_input()] = edge;
362	  }
363	
364	  for (int i = 0; i < num_inputs(); ++i) {
365	    if ((*input_edges)[i] == nullptr) {
366	      return absl::InvalidArgumentError(
367	          absl::StrCat("Missing edge input number: ", i));
368	    }
369	  }
370	  return absl::OkStatus();
371	}
