549	Node* Graph::AddNode(NodeDef node_def, absl::Status* status) {
550	  const OpRegistrationData* op_reg_data;
551	  status->Update(ops_.LookUp(node_def.op(), &op_reg_data));
552	  if (!status->ok()) return nullptr;
553	
554	  DataTypeVector inputs;
555	  DataTypeVector outputs;
556	  status->Update(
557	      InOutTypesForNode(node_def, op_reg_data->op_def, &inputs, &outputs));
558	  if (!status->ok()) {
559	    *status = AttachDef(*status, node_def);
560	    return nullptr;
561	  }
562	
563	  Node::NodeClass node_class = op_reg_data->is_function_op
564	                                   ? Node::NC_FUNCTION_OP
565	                                   : Node::GetNodeClassForOp(node_def.op());
566	
567	  if (node_def.has_experimental_type()) {
568	    VLOG(3) << "AddNode: node has type set, skipping type constructor "
569	            << node_def.name();
570	  } else {
571	    if (op_reg_data->type_ctor != nullptr) {
572	      VLOG(3) << "AddNode: found type constructor for " << node_def.name();
573	      absl::Status s =
574	          full_type::SpecializeType(AttrSlice(node_def), op_reg_data->op_def,
575	                                    *(node_def.mutable_experimental_type()));
576	      if (!s.ok()) {
577	        *status = absl::InvalidArgumentError(
578	            absl::StrCat("type error: ", s.ToString()));
579	        VLOG(3) << "AddNode: type inference failed for " << node_def.name()
580	                << ": " << s;
581	        return nullptr;
582	      }
583	    } else {
584	      VLOG(3) << "AddNode: no type constructor for " << node_def.name();
585	    }
586	  }
587	
588	  Node* node = AllocateNode(
589	      std::make_shared<NodeProperties>(&op_reg_data->op_def,
590	                                       std::move(node_def), inputs, outputs),
591	      nullptr, node_class);
592	  return node;
593	}
594	
595	Node* Graph::CopyNode(const Node* node) {
596	  DCHECK(!node->IsSource());
597	  DCHECK(!node->IsSink());
598	  Node* copy = AllocateNode(node->props_, node, node->class_);
599	  copy->set_assigned_device_name(node->assigned_device_name());
600	
601	  // Since the OpDef of a function may be owned by the Graph that owns 'node',
602	  // relookup the OpDef in the target graph. If it differs, then clone the
603	  // node properties with the updated OpDef.
604	  const OpDef* op_def;
605	  CHECK_OK(ops_.LookUpOpDef(node->type_string(), &op_def));
606	  if (op_def != node->props_->op_def) {
607	    copy->MaybeCopyOnWrite();
608	    copy->props_->op_def = op_def;
609	  }
610	  copy->SetStackTrace(node->GetStackTrace());
611	
612	  return copy;
613	}
614	
615	void Graph::RemoveNode(Node* node) {
616	  DCHECK_OK(IsValidNode(node)) << node->DebugString();
617	  DCHECK(!node->IsSource());
618	  DCHECK(!node->IsSink());
619	
620	  // Remove any edges involving this node.
621	  for (const Edge* e : node->in_edges_) {
622	    CHECK_EQ(e->src_->out_edges_.erase(e), size_t{1});
623	    edges_[e->id_] = nullptr;
624	    RecycleEdge(e);
625	    --num_edges_;
626	  }
627	  node->in_edges_.clear();
628	  for (const Edge* e : node->out_edges_) {
629	    CHECK_EQ(e->dst_->in_edges_.erase(e), size_t{1});
630	    edges_[e->id_] = nullptr;
631	    RecycleEdge(e);
632	    --num_edges_;
633	  }
634	  node->out_edges_.clear();
635	  ReleaseNode(node);
636	}
637	
638	const Edge* Graph::AddEdge(Node* source, int x, Node* dest, int y) {
639	  DCHECK_OK(IsValidNode(source)) << source->DebugString();
640	  DCHECK_OK(IsValidNode(dest)) << dest->DebugString();
641	
642	  // source/sink must only be linked via control slots, and
643	  // control slots must only be linked to control slots.
644	  if (source == source_node() || dest == sink_node() || x == kControlSlot ||
645	      y == kControlSlot) {
646	    DCHECK_EQ(x, kControlSlot) << source->DebugString();
647	    DCHECK_EQ(y, kControlSlot) << dest->DebugString();
648	  }
649	
650	  Edge* e = nullptr;
651	  if (free_edges_.empty()) {
652	    e = new (arena_.Alloc(sizeof(Edge))) Edge;  // placement new
653	  } else {
654	    e = free_edges_.back();
655	    free_edges_.pop_back();
656	  }
657	  e->id_ = edges_.size();
658	  e->src_ = source;
659	  e->dst_ = dest;
660	  e->src_output_ = x;
661	  e->dst_input_ = y;
662	  CHECK(source->out_edges_.insert(e).second);
663	  CHECK(dest->in_edges_.insert(e).second);
664	  edges_.push_back(e);
665	  ++num_edges_;
666	
667	  return e;
668	}
