670	void Graph::RemoveEdge(const Edge* e) {
671	  DCHECK_OK(IsValidNode(e->src_)) << e->src_->DebugString();
672	  DCHECK_OK(IsValidNode(e->dst_)) << e->dst_->DebugString();
673	  CHECK_EQ(e->src_->out_edges_.erase(e), size_t{1});
674	  CHECK_EQ(e->dst_->in_edges_.erase(e), size_t{1});
675	  CHECK_EQ(e, edges_[e->id_]);
676	  CHECK_GT(num_edges_, 0);
677	
678	  edges_[e->id_] = nullptr;
679	  RecycleEdge(e);
680	  --num_edges_;
681	}
