687	const Edge* Graph::AddControlEdge(Node* source, Node* dest,
688	                                  bool allow_duplicates) {
689	  if (!allow_duplicates) {
690	    for (const Edge* edge : dest->in_edges()) {
691	      if (edge->IsControlEdge() && edge->src() == source) {
692	        // The requested edge already exists.
693	        return nullptr;
694	      }
695	    }
696	  }
697	  // Modify dest's NodeDef if necessary.
698	  if (!source->IsSource() && !dest->IsSink() && !allow_duplicates) {
699	    // Check if this input is already in dest's NodeDef.
700	    const std::string new_input = absl::StrCat("^", source->name());
701	    bool input_exists = false;
702	    for (const std::string& input : dest->props_->node_def.input()) {
703	      if (input == new_input) {
704	        input_exists = true;
705	        break;
706	      }
707	    }
708	    if (!input_exists) {
709	      dest->MaybeCopyOnWrite();
710	      dest->props_->node_def.add_input(new_input);
711	    }
712	  }
713	  return AddEdge(source, kControlSlot, dest, kControlSlot);
714	}
715	
716	void Graph::RemoveControlEdge(const Edge* e) {
717	  if (!e->src_->IsSource() && !e->dst_->IsSink()) {
718	    e->dst_->MaybeCopyOnWrite();
719	    std::string e_src_name = absl::StrCat("^", e->src_->name());
720	    auto* inputs = e->dst_->props_->node_def.mutable_input();
721	    for (auto it = inputs->begin(); it != inputs->end(); ++it) {
722	      if (*it == e_src_name) {
723	        inputs->erase(it);
724	        break;
725	      }
726	    }
727	  }
728	  RemoveEdge(e);
729	}
