740	absl::Status Graph::UpdateEdge(Node* new_src, int new_src_index, Node* dst,
741	                               int dst_index) {
742	  TF_RETURN_IF_ERROR(IsValidOutputTensor(new_src, new_src_index));
743	  TF_RETURN_IF_ERROR(IsValidInputTensor(dst, dst_index));
744	  const Edge* e = FindEdge(dst, dst_index);
745	  if (e == nullptr) {
746	    return absl::InvalidArgumentError(
747	        absl::StrCat("Couldn't find edge to ", FormatNodeForError(*dst)));
748	  }
749	  RemoveEdge(e);
750	  AddEdge(new_src, new_src_index, dst, dst_index);
751	  dst->MaybeCopyOnWrite();
752	  (*dst->props_->node_def.mutable_input())[dst_index] =
753	      absl::StrCat(new_src->name(), ":", new_src_index);
754	  return absl::OkStatus();
755	}
