767	absl::Status Graph::AddWhileInputHack(Node* new_src, int new_src_index,
768	                                      Node* dst) {
769	  if (!dst->IsWhileNode()) {
770	    return absl::InternalError(absl::StrCat(
771	        "dst argument to AddWhileEdgeHack should be a While op, got: ",
772	        dst->DebugString()));
773	  }
774	  TF_RETURN_IF_ERROR(IsValidOutputTensor(new_src, new_src_index));
775	  // Find the current number of data inputs. We'll add the new edge to the next
776	  // missing data input.
777	  int dst_index = 0;
778	  for (const Edge* edge : dst->in_edges()) {
779	    if (edge->IsControlEdge()) continue;
780	    ++dst_index;
781	  }
782	  TF_RETURN_IF_ERROR(IsValidInputTensor(dst, dst_index));
783	  AddEdge(new_src, new_src_index, dst, dst_index);
784	  dst->MaybeCopyOnWrite();
785	  dst->props_->node_def.add_input(
786	      absl::StrCat(new_src->name(), ":", new_src_index));
787	  return absl::OkStatus();
788	}
