843	void Graph::ToGraphDefSubRange(GraphDef* graph_def, int from_node_id,
844	                               bool include_flib_def,
845	                               bool include_debug_info) const {
846	  graph_def->Clear();
847	  *graph_def->mutable_versions() = versions();
848	
849	  if (include_flib_def) {
850	    *graph_def->mutable_library() = ops_.ToProto();
851	  }
852	  if (include_debug_info) {
853	    *graph_def->mutable_debug_info() = BuildDebugInfo();
854	  }
855	
856	  graph_def->mutable_node()->Reserve(std::max(1, num_nodes() - from_node_id));
857	
858	  std::vector<const Edge*>
859	      inputs;  // Construct this outside the loop for speed.
860	  for (auto id = from_node_id; id < num_node_ids(); ++id) {
861	    const Node* node = FindNodeId(id);
862	    if (node == nullptr || !node->IsOp()) continue;
863	    NodeDef* node_def = graph_def->add_node();
864	    *node_def = node->def();
865	
866	    // Use the node's assigned device, if any, instead of the device requested
867	    // in the NodeDef.
868	    if (!node->assigned_device_name().empty()) {
869	      node_def->set_device(node->assigned_device_name());
870	    }
871	
872	    // Get the inputs for this Node.  We make sure control inputs are
873	    // after data inputs, as required by GraphDef.
874	    inputs.clear();
875	    inputs.resize(node->num_inputs(), nullptr);
876	    for (const Edge* edge : node->in_edges()) {
877	      if (edge->IsControlEdge()) {
878	        inputs.push_back(edge);
879	      } else {
880	        DCHECK(edge->dst_input() < inputs.size())
881	            << "Edge " << edge->DebugString()
882	            << " is overflowing the expected number of inputs ("
883	            << node->num_inputs() << ") for node " << node->DebugString();
884	        CHECK(inputs[edge->dst_input()] == nullptr)
885	            << "Edge " << edge->src()->name() << "->" << edge->dst()->name()
886	            << " conflicts with pre-existing input edge "
887	            << inputs[edge->dst_input()]->src()->name() << "->"
888	            << inputs[edge->dst_input()]->dst()->name();
889	
890	        inputs[edge->dst_input()] = edge;
891	      }
892	    }
893	    // Sort the control inputs for more predictable serialization.
894	    std::sort(inputs.begin() + node->num_inputs(), inputs.end(),
895	              [](const Edge* a, const Edge* b) -> bool {
896	                return a->src()->name() < b->src()->name();
897	              });
898	    node_def->clear_input();
899	    node_def->mutable_input()->Reserve(inputs.size());
900	
901	    for (size_t i = 0; i < inputs.size(); ++i) {
902	      const Edge* edge = inputs[i];
903	      if (edge == nullptr) {
904	        if (i < node->requested_inputs().size()) {
905	          node_def->add_input(node->requested_inputs()[i]);
906	        } else {
907	          node_def->add_input("");
908	        }
909	      } else {
910	        const Node* src = edge->src();
911	        if (!src->IsOp()) continue;
912	        AddInput(node_def, src->name(), edge->src_output());
913	      }
914	    }
915	  }
916	}
