922	absl::Status Graph::IsValidNode(const Node* node) const {
923	  if (node == nullptr) {
924	    return absl::InvalidArgumentError("Node is null");
925	  }
926	  const int id = node->id();
927	  if (id < 0) {
928	    return absl::InvalidArgumentError(
929	        absl::StrCat("node id ", id, " is less than zero"));
930	  }
931	  if (static_cast<size_t>(id) >= nodes_.size()) {
932	    return absl::InvalidArgumentError(
933	        absl::StrCat("node id ", id, " is >= than number of nodes in graph ",
934	                     nodes_.size()));
935	  }
936	  if (nodes_[id] != node) {
937	    return absl::InvalidArgumentError(
938	        absl::StrCat("Node with id ", id,
939	                     " is different from the passed in node. "
940	                     "Does it belong to a different graph?"));
941	  }
942	  return absl::OkStatus();
