967	Node* Graph::AllocateNode(std::shared_ptr<NodeProperties> props,
968	                          const Node* cost_node, Node::NodeClass node_class) {
969	  Node* node = nullptr;
970	  if (free_nodes_.empty()) {
971	    node = new (arena_.Alloc(sizeof(Node))) Node;  // placement new
972	  } else {
973	    node = free_nodes_.back();
974	    free_nodes_.pop_back();
975	  }
976	  node->graph_ = this;
977	  const int id = nodes_.size();
978	  int cost_id = cost_node ? cost_node->cost_id() : id;
979	  node->Initialize(id, cost_id, std::move(props), node_class);
980	  nodes_.push_back(node);
981	  ++num_nodes_;
982	  return node;
983	}
