993	// Ensures that 'device_name' is present in the device name table, and returns
994	// the index of that device name. The index is stable, and can be used in
995	// calls to Node::set_assigned_device_name_index().
996	int Graph::InternDeviceName(const std::string& device_name) {
997	  // Special case, very common.  Also, this allows us to use a single map
998	  // lookup below, instead of two.  The 'if (index_cell > 0)' test below
999	  // relies on this check.
1000	  if (device_name.empty()) {
1001	    return 0;
1002	  }
1003	
1004	  int& index_cell = device_names_map_[device_name];
1005	  if (index_cell > 0) {
1006	    return index_cell;
1007	  }
1008	
1009	  const int index = device_names_map_.size();
1010	  index_cell = index;
1011	  device_names_.push_back(device_name);
1012	  return index;
1013	}
