1015	absl::Status Graph::AddWhileContext(absl::string_view frame_name,
1016	                                    std::vector<Node*> enter_nodes,
1017	                                    std::vector<Node*> exit_nodes,
1018	                                    OutputTensor cond_output,
1019	                                    std::vector<OutputTensor> body_inputs,
1020	                                    std::vector<OutputTensor> body_outputs,
1021	                                    WhileContext** result) {
1022	  auto pair = while_ctxs_.insert(std::pair<std::string, WhileContext>(
1023	      std::string(frame_name),
1024	      WhileContext(frame_name, std::move(enter_nodes), std::move(exit_nodes),
1025	                   cond_output, std::move(body_inputs),
1026	                   std::move(body_outputs))));
1027	  if (!pair.second) {
1028	    *result = nullptr;
1029	    return absl::InvalidArgumentError(absl::StrCat(
1030	        "WhileContext with frame name '", frame_name, "' already exists"));
1031	  }
1032	  *result = &pair.first->second;
1033	  return absl::OkStatus();
1034	}
