1066	GraphDebugInfo Graph::BuildDebugInfo() const {
1067	  // Gather stack traces for all nodes associated with function definitions.
1068	  // Give these a key of <node_name> '@' <function_name>.
1069	  GraphDebugInfoBuilder builder;
1070	  for (const std::string& function_name : flib_def().ListFunctionNames()) {
1071	    if (core::RefCountPtr<FunctionRecord> function_record =
1072	            flib_def().FindRecord(function_name)) {
1073	      builder.AccumulateStackTracesMap(function_record->stack_traces(),
1074	                                       absl::StrCat("@", function_name));
1075	    }
1076	  }
1077	
1078	  // Other nodes will use the node name as the map key.
1079	  for (const Node* node : nodes()) {
1080	    if (node == nullptr || !node->IsOp()) {
1081	      continue;
1082	    }
1083	    const std::shared_ptr<AbstractStackTrace>& stack_trace =
1084	        node->GetStackTrace();
1085	    if (stack_trace != nullptr) {
1086	      builder.AccumulateStackTrace(stack_trace, node->name());
1087	    }
1088	  }
1089	
1090	  return builder.Build();
1091	}
